        self.poisoned = true;
        let bytes =
            physical::read_stable_image(&mut self.file).map_err(|_| StoreError::Indeterminate)?;
        let replayed = self
            .replay_current_image(&bytes)
            .map_err(|_| StoreError::Indeterminate)?;
